; switch.asm -- chapter 21: a Graphic I page moved into text mode
; generated by gen21.py
        INCLUDE "msx.inc"
        OUTPUT "switch.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
; The fix for bits.asm: a Graphic I page, shown; then, with the display off,
; text mode's tables written from it, R#7 given an ink, and all of R#1.
buf     EQU VARS + $20          ; a row of names on its way
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the page is drawn
        VDP_REG 0, $00          ; Graphic I: 32 x 24 characters
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $80          ; colours            $2000
        VDP_REG 4, $00          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; the BIOS character set: 256 x 8 bytes
        ld hl, (CGTABL)
        ld bc, 2048
.font:  ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .font
        VRAM_WRITE $0008        ; characters 1 and 2: the bit boxes
        ld hl, boxes
        ld b, 16
.box:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz .box
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld b, 32
        ld a, $1F
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; names: all spaces
        ld bc, 768
.clr:   ld a, ' '
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .clr
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        ld b, 0
        ld c, 0
        ld hl, w0
        call puts
        ld b, 2
        ld c, 0
        ld hl, w1
        call puts
        ld b, 4
        ld c, 0
        ld hl, w2
        call puts
        ld b, 6
        ld c, 0
        ld hl, w3
        call puts
        VDP_REG 1, $C0          ; the Graphic I page on
        ld b, 8
        call frames
sw:     VDP_REG 1, $90          ; 16 KB, M1: text mode, the display off
        VRAM_WRITE $0800        ; the BIOS's 256 characters, 2,048 bytes
        ld hl, (CGTABL)
        ld c, VDP_DATA
        ld d, 8
font:   ld b, 0
        otir
        dec d
        jr nz, font
clr:    VRAM_WRITE $0000        ; text mode's 960 names: spaces
        ld bc, 960
sp:     ld a, ' '
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, sp
names:  ld hl, $1800            ; the page's names, a row at a time,
        ld de, $0004            ; to text mode's, four columns in
        ld b, 24
row:    push bc
        ld a, l                 ; HL: an address to read (bit 6 at 0)
        out (VDP_CTRL), a
        ld a, h
        out (VDP_CTRL), a
        push hl
        ld hl, buf
        ld bc, 32 * 256 + VDP_DATA
        inir                    ; the display off: as fast as it goes
        ld a, e                 ; DE: an address to write
        out (VDP_CTRL), a
        ld a, d
        or $40
        out (VDP_CTRL), a
        ld hl, buf
        ld b, 32
        otir
        pop hl
        ld bc, 32
        add hl, bc              ; the next row of 32
        ex de, hl
        ld bc, 40
        add hl, bc              ; the next row of 40
        ex de, hl
        pop bc
        djnz row
regs:   VDP_REG 2, $00          ; names    $0000
        VDP_REG 4, $01          ; patterns $0800
        VDP_REG 7, $1F          ; ink black, backdrop white
on:     VDP_REG 1, $D0          ; text mode, the display on
done:   jr done

; frames: wait for B frame flags, the interrupts off (chapter 19's status)
frames: in a, (VDP_CTRL)        ; bit 7, F: a frame has ended
        rla
        jr nc, frames
        djnz frames
        ret
w0:     db "A PAGE MOVED TO TEXT MODE:", 0
w1:     db "THE NAMES COPIED FOUR COLUMNS IN", 0
w2:     db "THE SHAPES TO $0800, R#7 AN INK,", 0
w3:     db "AND R#1 WRITTEN WHOLE.", 0

; at: B = row (0-23), C = column (0-31) -> the VDP's write address is that
;     cell of the name table. Keeps BC, DE. Uses A, HL.
at:     push de
        ld l, b
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl              ; row x 32
        ld e, c
        ld d, $18
        add hl, de              ; + $1800 + column
        ld a, l
        out (VDP_CTRL), a
        ld a, h
        or $40
        out (VDP_CTRL), a
        pop de
        ret

; putc: A = character, B = row, C = column. Keeps BC, DE, HL.
putc:   push hl
        push af
        call at
        pop af
        out (VDP_DATA), a
        pop hl
        ret

; puts: HL = text ending in 0, B = row, C = column; C moves on.
puts:   ld a, (hl)
        or a
        ret z
        call putc
        inc hl
        inc c
        jr puts

; puthex: A = a byte, as two hexadecimal digits; C moves on by 2.
puthex: push af
        rrca
        rrca
        rrca
        rrca                    ; the high four bits first
        call hexdig
        pop af
hexdig: and %00001111
        add a, '0'
        cp '9' + 1
        jr c, .digit
        add a, 'A' - '9' - 1    ; 10-15 become A-F
.digit: call putc
        inc c
        ret
boxes:                          ; characters 1 (empty box) and 2 (filled)
        db %11111110, %10000010, %10000010, %10000010, %10000010, %10000010, %11111110, %00000000
        db %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %00000000
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
